import catalogue from "./catalogue.json";

/**
 * Catalogue data, generated by crawling all 491 legacy khalsa.co.in pages.
 * Shapes mirror the planned Sanity schema, so swapping these accessors for
 * GROQ queries later is a one-file change.
 *
 * Coverage: 398 products, 12 categories, 491 legacy paths mapped.
 * 141 products carry no specification table because the legacy page did not
 * have one either — several were commented out in the original HTML.
 */

export type Spec = { label: string; value: string };

export type Product = {
  code: string;
  slug: string;
  title: string;
  category: string;
  specs: Spec[];
  images: string[];
  legacyPath: string;
  seoTitle?: string;
  seoDescription?: string;
};

export type Category = {
  slug: string;
  title: string;
  group: "play" | "fitness" | "sports" | "surfaces";
  intro: string;
  count: number;
  gallery: string[];
  legacyPaths: string[];
};

export const PRODUCTS = catalogue.products as Product[];
export const CATEGORIES = catalogue.categories as Category[];
export const LEGACY_REDIRECTS = catalogue.legacyRedirects as Record<string, string>;

