/**
 * Range accents. Colour here is wayfinding, not decoration — across twelve
 * ranges a consistent hue is how someone keeps their place. Every value is
 * >= 4.5:1 on white, so they are safe as text as well as rules.
 */
export const GROUP_ACCENT: Record<Category["group"], { hex: string; ratio: string }> = {
  play: { hex: "#1A5FB4", ratio: "5.8:1" },
  fitness: { hex: "#B3121B", ratio: "6.4:1" },
  sports: { hex: "#146B3A", ratio: "6.0:1" },
  surfaces: { hex: "#8A5A00", ratio: "5.5:1" },
};

export function accentFor(slug: string) {
  const c = CATEGORIES.find((x) => x.slug === slug);
  return c ? GROUP_ACCENT[c.group].hex : "var(--text)";
}

/* ── accessors — swap for GROQ when Sanity lands ── */

export const getCategories = () => CATEGORIES;
export const getCategory = (slug: string) => CATEGORIES.find((c) => c.slug === slug);
export const getProducts = (categorySlug?: string) =>
  categorySlug ? PRODUCTS.filter((p) => p.category === categorySlug) : PRODUCTS;
export const getProduct = (categorySlug: string, slug: string) =>
  PRODUCTS.find((p) => p.category === categorySlug && p.slug === slug);
export const getRelated = (p: Product, limit = 4) =>
  PRODUCTS.filter((x) => x.category === p.category && x.slug !== p.slug).slice(0, limit);

/** Categories that carry products, for nav and listing pages. */
export const getStockedCategories = () => CATEGORIES.filter((c) => c.count > 0);
